reply:
```turtle
@prefix ht:   <http://example.org/onto/hypertension#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

ht: a owl:Ontology ;
    rdfs:label "Hypertension Ontology"@en ;
    rdfs:comment "An ontology modelling hypertension classification, etiology, measurement, treatment, risk factors and target-organ damage, as stated in the source corpus."@en .

#################################################################
# 1. REIFIED MEASUREMENT AXIS
#################################################################

ht:BloodPressureReading a owl:Class ;
    rdfs:label "Blood Pressure Reading"@en ;
    skos:definition "A measured pair of systolic and diastolic blood pressure values, expressed in millimetres of mercury."@en ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] ,
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] .

ht:hasSystolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has systolic value"@en ;
    skos:definition "The numeric systolic blood pressure value, in mmHg, of a blood pressure reading (the maximum pressure during one heartbeat)."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range xsd:integer .

ht:hasDiastolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diastolic value"@en ;
    skos:definition "The numeric diastolic blood pressure value, in mmHg, of a blood pressure reading (the minimum pressure between heartbeats)."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range xsd:integer .

ht:BloodPressureCategory a owl:Class ;
    rdfs:label "Blood Pressure Category"@en ;
    skos:definition "A classification band of the ACC/AHA 2017 scheme (Normal, Elevated, Stage 1 Hypertension, Stage 2 Hypertension) into which a blood pressure reading is assigned on the basis of its systolic and/or diastolic value."@en ;
    rdfs:comment "Competing guideline band schemes (ESC/ESH, JNC7/8, WHO, NICE, ISH) use different thresholds for the same labels; only the ACC/AHA 2017 scheme is modelled as classes here."@en .

ht:hasBloodPressureCategory a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has blood pressure category"@en ;
    skos:definition "Relates a blood pressure reading to the ACC/AHA 2017 category band into which it is classified."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:BloodPressureCategory .

ht:isBloodPressureCategoryOf a owl:ObjectProperty ;
    rdfs:label "is blood pressure category of"@en ;
    skos:definition "Inverse of has blood pressure category."@en ;
    owl:inverseOf ht:hasBloodPressureCategory ;
    rdfs:domain ht:BloodPressureCategory ; rdfs:range ht:BloodPressureReading .

ht:NormalBloodPressure a owl:Class ;
    rdfs:label "Normal Blood Pressure"@en ;
    skos:definition "A blood pressure reading with systolic pressure less than 120 mmHg and diastolic pressure less than 80 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 120 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ] ) ] .

ht:ElevatedBloodPressure a owl:Class ;
    rdfs:label "Elevated Blood Pressure"@en ;
    skos:altLabel "Prehypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure of 120 to 129 mmHg and diastolic pressure less than 80 mmHg."@en ;
    rdfs:comment "Previously termed prehypertension under JNC 7 (120-139/80-89 mmHg); the ACC/AHA 2017 scheme reassigned part of that range to Stage 1 Hypertension."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:minInclusive 120 ] [ xsd:maxInclusive 129 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ] ) ] .

ht:Stage1Hypertension a owl:Class ;
    rdfs:label "Stage 1 Hypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure of 130 to 139 mmHg or diastolic pressure of 80 to 89 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Class ; owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 130 ] [ xsd:maxInclusive 139 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 80 ] [ xsd:maxInclusive 89 ] ) ] ]
        ) ] ) ] .

ht:Stage2Hypertension a owl:Class ;
    rdfs:label "Stage 2 Hypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure of 140 mmHg or higher or diastolic pressure of 90 mmHg or higher."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Class ; owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 140 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 90 ] ) ] ]
        ) ] ) ] .

owl:AllDisjointClasses [ owl:members ( ht:NormalBloodPressure ht:ElevatedBloodPressure
    ht:Stage1Hypertension ht:Stage2Hypertension ) ] .

#################################################################
# 2. HYPERTENSION (DISEASE) + SECONDARY CAUSE AXIS
#################################################################

ht:Hypertension a owl:Class ;
    rdfs:label "Hypertension"@en ;
    skos:altLabel "High Blood Pressure"@en , "HTN"@en ;
    skos:definition "A chronic medical condition characterised by sustained elevation of arterial blood pressure in the arteries."@en ;
    rdfs:comment "Diagnostic threshold is contested across guidelines; see hasDiagnosticSystolicThreshold."@en .

ht:hasDiagnosticSystolicThreshold a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diagnostic systolic threshold"@en ;
    skos:definition "The systolic blood pressure value, in mmHg, at or above which hypertension is diagnosed."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range xsd:integer ;
    rdfs:comment "The 2017 ACC/AHA guideline sets this threshold at 130 mmHg, whereas ESC/ESH, JNC7/8, WHO and ISH guidelines set it at 140 mmHg. This is a genuine, documented conflict in the corpus and is not resolved into separate guideline subclasses."@en .

ht:hasSecondaryCause a owl:ObjectProperty ;
    rdfs:label "has secondary cause"@en ;
    skos:definition "Relates a case of hypertension to an identifiable underlying condition, medication, or substance responsible for the elevated blood pressure."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:SecondaryCause .

ht:isSecondaryCauseOf a owl:ObjectProperty ;
    rdfs:label "is secondary cause of"@en ;
    skos:definition "Inverse of has secondary cause."@en ;
    owl:inverseOf ht:hasSecondaryCause ;
    rdfs:domain ht:SecondaryCause ; rdfs:range ht:Hypertension .

ht:hasBloodPressureReading a owl:ObjectProperty ;
    rdfs:label "has blood pressure reading"@en ;
    skos:definition "Relates a form of hypertension to a blood pressure reading that evidences or defines it."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:BloodPressureReading .

ht:isBloodPressureReadingOf a owl:ObjectProperty ;
    rdfs:label "is blood pressure reading of"@en ;
    owl:inverseOf ht:hasBloodPressureReading ;
    skos:definition "Inverse of has blood pressure reading."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:Hypertension .

ht:hasTargetOrganDamage a owl:ObjectProperty ;
    rdfs:label "has target organ damage"@en ;
    skos:definition "Relates a hypertensive condition to acute or chronic damage sustained by a target organ as a result of elevated blood pressure."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:TargetOrganDamage .

ht:isTargetOrganDamageOf a owl:ObjectProperty ;
    rdfs:label "is target organ damage of"@en ;
    owl:inverseOf ht:hasTargetOrganDamage ;
    skos:definition "Inverse of has target organ damage."@en ;
    rdfs:domain ht:TargetOrganDamage ; rdfs:range ht:Hypertension .

ht:hasAntihypertensive a owl:ObjectProperty ;
    rdfs:label "has antihypertensive"@en ;
    skos:definition "Relates a hypertensive condition to a class of medication used to lower blood pressure in its management."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:Antihypertensive .

ht:isAntihypertensiveOf a owl:ObjectProperty ;
    rdfs:label "is antihypertensive of"@en ;
    owl:inverseOf ht:hasAntihypertensive ;
    skos:definition "Inverse of has antihypertensive."@en ;
    rdfs:domain ht:Antihypertensive ; rdfs:range ht:Hypertension .

ht:hasRiskFactor a owl:ObjectProperty ;
    rdfs:label "has risk factor"@en ;
    skos:definition "Relates hypertension to a modifiable or non-modifiable factor associated with increased risk of developing the condition."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:RiskFactor .

ht:isRiskFactorOf a owl:ObjectProperty ;
    rdfs:label "is risk factor of"@en ;
    owl:inverseOf ht:hasRiskFactor ;
    skos:definition "Inverse of has risk factor."@en ;
    rdfs:domain ht:RiskFactor ; rdfs:range ht:Hypertension .

#################################################################
# 2a. PRIMARY / SECONDARY HYPERTENSION
#################################################################

ht:PrimaryHypertension a owl:Class ;
    rdfs:label "Primary Hypertension"@en ;
    skos:altLabel "Essential Hypertension"@en , "Idiopathic Hypertension"@en ;
    skos:definition "Hypertension with no single identifiable cause, accounting for approximately 85-95% of cases and arising from a complex interaction of genetic predisposition and environmental/lifestyle factors."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:SecondaryHypertension a owl:Class ;
    rdfs:label "Secondary Hypertension"@en ;
    skos:altLabel "Inessential Hypertension"@en ;
    skos:definition "Hypertension that is secondary to an identifiable underlying cause, such as a medical condition, medication, or substance, accounting for roughly 5-15% of cases."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasSecondaryCause ; owl:someValuesFrom ht:SecondaryCause ] ) ] .

owl:AllDisjointClasses [ owl:members ( ht:PrimaryHypertension ht:SecondaryHypertension ) ] .

#################################################################
# 2b. ISOLATED SYSTOLIC HYPERTENSION
#################################################################

ht:IsolatedSystolicHypertension a owl:Class ;
    rdfs:label "Isolated Systolic Hypertension"@en ;
    skos:definition "Hypertension characterised by a disproportionate rise in systolic pressure with a preserved or low diastolic pressure, producing a widened pulse pressure; the predominant form of hypertension in older adults, resulting chiefly from arterial stiffening."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasBloodPressureReading ; owl:someValuesFrom
            [ owl:intersectionOf ( ht:BloodPressureReading
                [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                    [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                      owl:withRestrictions ( [ xsd:minExclusive 140 ] ) ] ]
                [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                    [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                      owl:withRestrictions ( [ xsd:maxExclusive 90 ] ) ] ] ) ] ] ) ] ;
    rdfs:comment "Traditional threshold: systolic >140 mmHg with diastolic <90 mmHg. Under the 2017 ACC/AHA guideline a systolic pressure of 130 mmHg or more is considered hypertensive at all ages; the corpus documents both values."@en .

#################################################################
# 2c. WHITE COAT / MASKED / RESISTANT HYPERTENSION
#################################################################

ht:WhiteCoatHypertension a owl:Class ;
    rdfs:label "White Coat Hypertension"@en ;
    skos:altLabel "White Coat Syndrome"@en , "WHT"@en ;
    skos:definition "A phenotype of labile hypertension in which blood pressure is elevated in a clinical setting (office) but normal out-of-office, believed to reflect anxiety at the clinic visit."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:MaskedHypertension a owl:Class ;
    rdfs:label "Masked Hypertension"@en ;
    skos:altLabel "MH"@en ;
    skos:definition "A phenotype in which office blood pressure is normal but out-of-office blood pressure is elevated, the inverse pattern to white coat hypertension; carries cardiovascular risk approaching that of sustained hypertension."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:ResistantHypertension a owl:Class ;
    rdfs:label "Resistant Hypertension"@en ;
    skos:definition "Hypertension that remains uncontrolled to goal despite adherence to three or more suitably dosed antihypertensive medications of different classes, one of which is a diuretic, after exclusion of the white coat effect; or hypertension controlled only on four or more agents."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasAntihypertensive ;
          owl:minQualifiedCardinality "3"^^xsd:nonNegativeInteger ; owl:onClass ht:Antihypertensive ] ) ] .

#################################################################
# 2d. HYPERTENSIVE CRISIS / URGENCY / EMERGENCY
#################################################################

ht:HypertensiveCrisis a owl:Class ;
    rdfs:label "Hypertensive Crisis"@en ;
    skos:definition "A severe, acute elevation of blood pressure, commonly defined as systolic pressure of 180 mmHg or more or diastolic pressure of 120 mmHg or more, divided into hypertensive urgency and hypertensive emergency according to the presence or absence of acute target-organ damage."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasBloodPressureReading ; owl:someValuesFrom
            [ a owl:Class ; owl:unionOf (
                [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                    [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                      owl:withRestrictions ( [ xsd:minInclusive 180 ] ) ] ]
                [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                    [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                      owl:withRestrictions ( [ xsd:minInclusive 120 ] ) ] ]
            ) ] ] ) ] .

ht:HypertensiveUrgency a owl:Class ;
    rdfs:label "Hypertensive Urgency"@en ;
    skos:definition "A hypertensive crisis without evidence of acute or progressive target-organ damage, typically managed with gradual oral blood pressure reduction over 24-48 hours."@en ;
    rdfs:subClassOf ht:HypertensiveCrisis .

ht:HypertensiveEmergency a owl:Class ;
    rdfs:label "Hypertensive Emergency"@en ;
    skos:definition "A hypertensive crisis accompanied by acute hypertension-mediated organ damage, representing a life-threatening condition requiring immediate, controlled reduction of blood pressure, usually with intravenous agents."@en ;
    rdfs:subClassOf ht:HypertensiveCrisis ;
    owl:equivalentClass [ owl:intersectionOf ( ht:HypertensiveCrisis
        [ a owl:Restriction ; owl:onProperty ht:hasTargetOrganDamage ; owl:someValuesFrom ht:TargetOrganDamage ] ) ] .

owl:AllDisjointClasses [ owl:members ( ht:HypertensiveUrgency ht:HypertensiveEmergency ) ] .

#################################################################
# 3. SECONDARY CAUSE HIERARCHY
#################################################################

ht:SecondaryCause a owl:Class ;
    rdfs:label "Secondary Cause"@en ;
    skos:definition "An identifiable underlying condition, medication, or substance that produces secondary hypertension."@en .

ht:RenalCause a owl:Class ;
    rdfs:label "Renal Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from kidney pathology, the most common category of secondary cause overall."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:RenalParenchymalDisease a owl:Class ;
    rdfs:label "Renal Parenchymal Disease"@en ;
    skos:definition "Disease of the kidney tissue itself, including diabetic nephropathy, glomerulonephritis, interstitial disorders, and polycystic kidney disease, that causes secondary hypertension."@en ;
    rdfs:subClassOf ht:RenalCause .

ht:Glomerulonephritis a owl:Class ;
    rdfs:label "Glomerulonephritis"@en ;
    skos:definition "Inflammatory disease of the renal glomeruli, a form of renal parenchymal disease causing secondary hypertension."@en ;
    rdfs:subClassOf ht:RenalParenchymalDisease .

ht:PolycysticKidneyDisease a owl:Class ;
    rdfs:label "Polycystic Kidney Disease"@en ;
    skos:definition "A hereditary renal parenchymal disorder characterised by multiple kidney cysts, associated with secondary hypertension."@en ;
    rdfs:subClassOf ht:RenalParenchymalDisease .

ht:RenovascularDisease a owl:Class ;
    rdfs:label "Renovascular Disease"@en ;
    skos:definition "Disease of the renal vasculature that produces hypertension through narrowing of the renal artery."@en ;
    rdfs:subClassOf ht:RenalCause .

ht:RenalArteryStenosis a owl:Class ;
    rdfs:label "Renal Artery Stenosis"@en ;
    skos:definition "Narrowing of the renal artery, a form of renovascular disease that is a recognised cause of secondary hypertension."@en ;
    rdfs:subClassOf ht:RenovascularDisease .

ht:EndocrineCause a owl:Class ;
    rdfs:label "Endocrine Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from a hormonal/endocrine disturbance."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:PrimaryAldosteronism a owl:Class ;
    rdfs:label "Primary Aldosteronism"@en ;
    skos:altLabel "Conn's Syndrome"@en ;
    skos:definition "Autonomous overproduction of aldosterone by the adrenal glands, due to an aldosterone-producing adenoma or bilateral adrenal hyperplasia, accounting for most endocrine-related secondary hypertension and found in up to one in five patients with resistant hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:Pheochromocytoma a owl:Class ;
    rdfs:label "Pheochromocytoma"@en ;
    skos:definition "A tumour that results in excessive secretion of norepinephrine and epinephrine, promoting vasoconstriction and secondary hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:CushingSyndrome a owl:Class ;
    rdfs:label "Cushing Syndrome"@en ;
    skos:definition "An endocrine disorder of excess glucocorticoids that is a recognised cause of secondary hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:ThyroidDisease a owl:Class ;
    rdfs:label "Thyroid Disease"@en ;
    skos:definition "Disease of the thyroid gland, including hyperthyroidism and hypothyroidism, recognised as a cause of secondary hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:Hyperthyroidism a owl:Class ;
    rdfs:label "Hyperthyroidism"@en ;
    skos:definition "Excess thyroid hormone production, a form of thyroid disease causing secondary hypertension."@en ;
    rdfs:subClassOf ht:ThyroidDisease .

ht:Hypothyroidism a owl:Class ;
    rdfs:label "Hypothyroidism"@en ;
    skos:definition "Deficient thyroid hormone production, a form of thyroid disease causing secondary hypertension."@en ;
    rdfs:subClassOf ht:ThyroidDisease .

ht:PrimaryHyperparathyroidism a owl:Class ;
    rdfs:label "Primary Hyperparathyroidism"@en ;
    skos:definition "Excess parathyroid hormone secretion, an endocrine cause of secondary hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:VascularCause a owl:Class ;
    rdfs:label "Vascular Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from a structural vascular abnormality."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:AorticCoarctation a owl:Class ;
    rdfs:label "Aortic Coarctation"@en ;
    skos:altLabel "Coarctation of the Aorta"@en ;
    skos:definition "A congenital narrowing of the aorta that is a vascular cause of secondary hypertension, typically affecting younger patients."@en ;
    rdfs:subClassOf ht:VascularCause .

ht:ObstructiveSleepApnea a owl:Class ;
    rdfs:label "Obstructive Sleep Apnea"@en ;
    skos:altLabel "OSA"@en ;
    skos:definition "A sleep-related breathing disorder that is one of the most common causes of secondary hypertension."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:DrugInducedCause a owl:Class ;
    rdfs:label "Drug Induced Cause"@en ;
    skos:definition "Secondary hypertension caused by a medication, herbal remedy, or recreational substance; identifying and discontinuing the agent may resolve the hypertension."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:NonsteroidalAntiInflammatoryDrug a owl:Class ;
    rdfs:label "Nonsteroidal Anti Inflammatory Drug"@en ;
    skos:altLabel "NSAID"@en ;
    skos:definition "A class of anti-inflammatory medication, such as ibuprofen, that is a recognised drug-induced cause of secondary hypertension."@en ;
    rdfs:subClassOf ht:DrugInducedCause .

ht:SympathomimeticDecongestant a owl:Class ;
    rdfs:label "Sympathomimetic Decongestant"@en ;
    skos:definition "A decongestant medication containing phenylephrine or pseudoephedrine that is a recognised drug-induced cause of secondary hypertension."@en ;
    rdfs:subClassOf ht:DrugInducedCause .

ht:Corticosteroid a owl:Class ;
    rdfs:label "Corticosteroid"@en ;
    skos:definition "A systemic glucocorticoid medication that is a recognised drug-induced cause of secondary hypertension."@en ;
    rdfs:subClassOf ht:DrugInducedCause .

ht:OralContraceptive a owl:Class ;
    rdfs:label "Oral Contraceptive"@en ;
    skos:definition "A birth control medication, including estrogen-containing preparations, that is a recognised drug-induced cause of secondary hypertension."@en ;
    rdfs:subClassOf ht:DrugInducedCause .

owl:AllDisjointClasses [ owl:members ( ht:RenalCause ht:EndocrineCause ht:VascularCause
    ht:ObstructiveSleepApnea ht:DrugInducedCause ) ] .

#################################################################
# 4. TARGET ORGAN DAMAGE HIERARCHY
#################################################################

ht:TargetOrganDamage a owl:Class ;
    rdfs:label "Target Organ Damage"@en ;
    skos:altLabel "Hypertension Mediated Organ Damage"@en ;
    skos:definition "Functional and morphological damage to the cardiovascular system, brain, kidneys, or eyes caused by chronic or acute elevated blood pressure."@en .

ht:HypertensiveHeartDisease a owl:Class ;
    rdfs:label "Hypertensive Heart Disease"@en ;
    skos:definition "Structural and functional changes in the left ventricle, left atrium, and coronary arteries resulting from chronic blood pressure elevation, including left ventricular hypertrophy, remodeling, and eventual heart failure."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:LeftVentricularHypertrophy a owl:Class ;
    rdfs:label "Left Ventricular Hypertrophy"@en ;
    skos:definition "Thickening of the left ventricular wall in response to sustained pressure overload; the hallmark structural manifestation of hypertensive heart disease."@en ;
    rdfs:subClassOf ht:HypertensiveHeartDisease .

ht:HypertensiveRetinopathy a owl:Class ;
    rdfs:label "Hypertensive Retinopathy"@en ;
    skos:definition "Damage to the retina and retinal circulation due to sustained or abrupt elevation of blood pressure, observable directly on fundoscopic examination and correlating with the severity and chronicity of hypertension."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:hasRetinalFinding a owl:ObjectProperty ;
    rdfs:label "has retinal finding"@en ;
    skos:definition "Relates hypertensive retinopathy to a specific retinal finding observed on fundoscopic examination."@en ;
    rdfs:domain ht:HypertensiveRetinopathy ; rdfs:range ht:RetinalFinding .

ht:isRetinalFindingOf a owl:ObjectProperty ;
    rdfs:label "is retinal finding of"@en ;
    owl:inverseOf ht:hasRetinalFinding ;
    skos:definition "Inverse of has retinal finding."@en ;
    rdfs:domain ht:RetinalFinding ; rdfs:range ht:HypertensiveRetinopathy .

ht:RetinalFinding a owl:Class ;
    rdfs:label "Retinal Finding"@en ;
    skos:definition "A specific vascular or structural abnormality of the retina observed on examination in association with hypertensive retinopathy."@en .

ht:ArteriolarNarrowing a owl:Class ;
    rdfs:label "Arteriolar Narrowing"@en ;
    skos:definition "Generalised or focal narrowing of the retinal arterioles, an early retinal finding of hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:ArteriovenousNicking a owl:Class ;
    rdfs:label "Arteriovenous Nicking"@en ;
    skos:altLabel "AV Nicking"@en , "AV Nipping"@en ;
    skos:definition "A retinal finding in which a vein appears compressed where a sclerotic arteriole crosses it."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:RetinalHemorrhage a owl:Class ;
    rdfs:label "Retinal Hemorrhage"@en ;
    skos:altLabel "Flame Hemorrhage"@en , "Blot Hemorrhage"@en ;
    skos:definition "Bleeding into the retinal tissue resulting from breakdown of the blood-retinal barrier in advanced hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:CottonWoolSpot a owl:Class ;
    rdfs:label "Cotton Wool Spot"@en ;
    skos:definition "A retinal finding reflecting focal retinal ischemia, seen in more advanced hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:HardExudate a owl:Class ;
    rdfs:label "Hard Exudate"@en ;
    skos:definition "Lipid deposits in the retina resulting from leakage through damaged retinal vessels in hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:Papilledema a owl:Class ;
    rdfs:label "Papilledema"@en ;
    skos:altLabel "Optic Disc Edema"@en ;
    skos:definition "Swelling of the optic disc, the most severe retinal finding, indicating malignant hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:HypertensiveNephropathy a owl:Class ;
    rdfs:label "Hypertensive Nephropathy"@en ;
    skos:altLabel "Hypertensive Kidney Disease"@en , "Nephrosclerosis"@en ;
    skos:definition "Kidney damage and failure attributable to chronic high blood pressure, characterised by nephrosclerosis: hardening and thickening of the small renal vessels, glomeruli, tubules, and interstitial tissue, reducing blood and oxygen supply and progressively lowering filtering capacity."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:HypertensiveEncephalopathy a owl:Class ;
    rdfs:label "Hypertensive Encephalopathy"@en ;
    skos:definition "Brain swelling and dysfunction caused by severely elevated blood pressure, presenting with headache, confusion, or visual disturbance; a neurological manifestation of hypertensive emergency."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:Stroke a owl:Class ;
    rdfs:label "Stroke"@en ;
    skos:definition "Ischemic or hemorrhagic cerebrovascular injury resulting from sustained or severely elevated blood pressure."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

owl:AllDisjointClasses [ owl:members ( ht:HypertensiveHeartDisease ht:HypertensiveRetinopathy
    ht:HypertensiveNephropathy ht:HypertensiveEncephalopathy ht:Stroke ) ] .

#################################################################
# 5. ANTIHYPERTENSIVE DRUG CLASS HIERARCHY
#################################################################

ht:Antihypertensive a owl:Class ;
    rdfs:label "Antihypertensive"@en ;
    skos:definition "A class of medication used to lower blood pressure in the treatment of hypertension."@en .

ht:ThiazideDiuretic a owl:Class ;
    rdfs:label "Thiazide Diuretic"@en ;
    skos:definition "A first-line antihypertensive drug class that blocks sodium reabsorption in the distal convoluted tubule of the nephron, promoting natriuresis and diuresis and reducing intravascular volume; considered, on best available evidence, the first-line treatment of choice."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:AngiotensinConvertingEnzymeInhibitor a owl:Class ;
    rdfs:label "Angiotensin Converting Enzyme Inhibitor"@en ;
    skos:altLabel "ACE Inhibitor"@en , "ACEI"@en ;
    skos:definition "A first-line antihypertensive drug class that inhibits the angiotensin-converting enzyme, reducing angiotensin II production and increasing bradykinin levels, thereby promoting vasodilation; contraindicated in pregnancy and associated with dry cough and angioedema."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:AngiotensinReceptorBlocker a owl:Class ;
    rdfs:label "Angiotensin Receptor Blocker"@en ;
    skos:altLabel "ARB"@en ;
    skos:definition "A first-line antihypertensive drug class that blocks the binding of angiotensin II to the AT1 receptor, with efficacy similar to ACE inhibitors but fewer adverse effects such as cough and angioedema; generally not combined with ACE inhibitors."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:CalciumChannelBlocker a owl:Class ;
    rdfs:label "Calcium Channel Blocker"@en ;
    skos:altLabel "CCB"@en ;
    skos:definition "A first-line antihypertensive drug class that inhibits calcium entry into cardiac and vascular smooth muscle via L-type voltage-gated calcium channels, comprising dihydropyridine and non-dihydropyridine subtypes."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:Dihydropyridine a owl:Class ;
    rdfs:label "Dihydropyridine"@en ;
    skos:definition "A subtype of calcium channel blocker that causes peripheral vasodilation by acting predominantly on vascular smooth muscle, preferred for the treatment of hypertension."@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker .

ht:NonDihydropyridine a owl:Class ;
    rdfs:label "Non Dihydropyridine"@en ;
    skos:definition "A subtype of calcium channel blocker, such as verapamil and diltiazem, that primarily affects cardiac contractility and atrioventricular conduction, making it better suited to the management of arrhythmias."@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker .

owl:AllDisjointClasses [ owl:members ( ht:Dihydropyridine ht:NonDihydropyridine ) ] .

ht:BetaBlocker a owl:Class ;
    rdfs:label "Beta Blocker"@en ;
    skos:definition "An antihypertensive drug class that inhibits catecholamines from binding to beta-adrenergic receptors, decreasing heart rate, cardiac contractility, and renin release; no longer first-line for uncomplicated hypertension but retained for patients with a compelling cardiac indication."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:MineralocorticoidReceptorAntagonist a owl:Class ;
    rdfs:label "Mineralocorticoid Receptor Antagonist"@en ;
    skos:altLabel "MRA"@en ;
    skos:definition "An antihypertensive drug class, such as spironolactone, used as an add-on agent in resistant hypertension and in the treatment of primary aldosteronism."@en ;
    rdfs:subClassOf ht:Antihypertensive .

owl:AllDisjointClasses [ owl:members ( ht:ThiazideDiuretic ht:AngiotensinConvertingEnzymeInhibitor
    ht:AngiotensinReceptorBlocker ht:CalciumChannelBlocker ht:BetaBlocker
    ht:MineralocorticoidReceptorAntagonist ) ] .

#################################################################
# 6. RISK FACTOR HIERARCHY
#################################################################

ht:RiskFactor a owl:Class ;
    rdfs:label "Risk Factor"@en ;
    skos:definition "A factor, modifiable or non-modifiable, associated with increased likelihood of developing hypertension."@en .

ht:ModifiableRiskFactor a owl:Class ;
    rdfs:label "Modifiable Risk Factor"@en ;
    skos:definition "A risk factor for hypertension that can be changed through behaviour or treatment, such as diet, weight, smoking, or activity level."@en ;
    rdfs:subClassOf ht:RiskFactor .

ht:ExcessDietarySalt a owl:Class ;
    rdfs:label "Excess Dietary Salt"@en ;
    skos:definition "High dietary sodium intake, a modifiable risk factor that increases the risk of developing hypertension; approximately 50-60% of patients are salt sensitive."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:Obesity a owl:Class ;
    rdfs:label "Obesity"@en ;
    skos:definition "Excess body weight, a modifiable risk factor for hypertension; weight reduction alone can lower systolic blood pressure by 5-20 mmHg."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:PhysicalInactivity a owl:Class ;
    rdfs:label "Physical Inactivity"@en ;
    skos:definition "Lack of regular exercise, a modifiable risk factor for hypertension."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:TobaccoUse a owl:Class ;
    rdfs:label "Tobacco Use"@en ;
    skos:definition "Smoking, a modifiable risk factor for hypertension and cardiovascular disease."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:ExcessiveAlcoholConsumption a owl:Class ;
    rdfs:label "Excessive Alcohol Consumption"@en ;
    skos:definition "High alcohol intake, a modifiable risk factor associated with higher blood pressure."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:NonModifiableRiskFactor a owl:Class ;
    rdfs:label "Non Modifiable Risk Factor"@en ;
    skos:definition "A risk factor for hypertension that cannot be changed, such as age, sex, race, or family history."@en ;
    rdfs:subClassOf ht:RiskFactor .

ht:AdvancedAge a owl:Class ;
    rdfs:label "Advanced Age"@en ;
    skos:definition "Increasing age, a non-modifiable risk factor; prevalence of hypertension rises to approximately 60% of individuals above age 60."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:FamilyHistoryOfHypertension a owl:Class ;
    rdfs:label "Family History Of Hypertension"@en ;
    skos:definition "A family history of high blood pressure, a non-modifiable risk factor reflecting genetic predisposition."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:GeneticPredisposition a owl:Class ;
    rdfs:label "Genetic Predisposition"@en ;
    skos:definition "Inherited genetic variants that influence individual salt sensitivity and blood pressure, a non-modifiable risk factor; more than 2,000 common genetic variants with small effects have been identified."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:Race a owl:Class ;
    rdfs:label "Race"@en ;
    skos:definition "Race or ethnicity, a non-modifiable risk factor that also influences first-line treatment selection in hypertension guidelines."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

owl:AllDisjointClasses [ owl:members ( ht:ModifiableRiskFactor ht:NonModifiableRiskFactor ) ] .

#################################################################
# 7. BLOOD PRESSURE MEASUREMENT
#################################################################

ht:BloodPressureMeasurementTechnique a owl:Class ;
    rdfs:label "Blood Pressure Measurement Technique"@en ;
    skos:definition "A technique by which the systolic and diastolic blood pressure values of a reading are obtained."@en .

ht:AuscultatoryMethod a owl:Class ;
    rdfs:label "Auscultatory Method"@en ;
    skos:definition "A blood pressure measurement technique using a stethoscope and sphygmomanometer, in which Korotkoff sounds heard as cuff pressure is released indicate systolic and diastolic pressure."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementTechnique .

ht:OscillometricMethod a owl:Class ;
    rdfs:label "Oscillometric Method"@en ;
    skos:definition "A blood pressure measurement technique used by automated devices, which calculates systolic, diastolic, and mean arterial pressure from oscillations in cuff pressure without requiring a clinician to listen for Korotkoff sounds."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementTechnique .

owl:AllDisjointClasses [ owl:members ( ht:AuscultatoryMethod ht:OscillometricMethod ) ] .

ht:BloodPressureMeasurementSetting a owl:Class ;
    rdfs:label "Blood Pressure Measurement Setting"@en ;
    skos:definition "The setting in which a blood pressure reading is obtained, such as the clinic office, ambulatory monitoring, or home monitoring."@en .

ht:OfficeBloodPressureMeasurement a owl:Class ;
    rdfs:label "Office Blood Pressure Measurement"@en ;
    skos:altLabel "Clinic Blood Pressure Measurement"@en ;
    skos:definition "Blood pressure measurement taken in a clinical setting such as a doctor's office, subject to the white coat effect."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementSetting .

ht:AmbulatoryBloodPressureMonitoring a owl:Class ;
    rdfs:label "Ambulatory Blood Pressure Monitoring"@en ;
    skos:altLabel "ABPM"@en ;
    skos:definition "Out-of-office blood pressure measurement at regular intervals over a full 24-hour sleep-wake cycle, regarded as the reference standard for distinguishing white coat and masked hypertension from sustained hypertension."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementSetting .

ht:HomeBloodPressureMonitoring a owl:Class ;
    rdfs:label "Home Blood Pressure Monitoring"@en ;
    skos:altLabel "HBPM"@en ;
    skos:definition "Out-of-office blood pressure measurement performed by the patient at home, found to be as accurate as 24-hour ambulatory monitoring for determining blood pressure levels."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementSetting .

owl:AllDisjointClasses [ owl:members ( ht:OfficeBloodPressureMeasurement
    ht:AmbulatoryBloodPressureMonitoring ht:HomeBloodPressureMonitoring ) ] .

ht:hasMeasurementTechnique a owl:ObjectProperty ;
    rdfs:label "has measurement technique"@en ;
    skos:definition "Relates a blood pressure reading to the technique (auscultatory or oscillometric) by which it was obtained."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:BloodPressureMeasurementTechnique .

ht:hasMeasurementSetting a owl:ObjectProperty ;
    rdfs:label "has measurement setting"@en ;
    skos:definition "Relates a blood pressure reading to the setting (office, ambulatory, or home) in which it was obtained."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:BloodPressureMeasurementSetting .

#################################################################
# 8. TOP-LEVEL KIND DISJOINTNESS
#################################################################

owl:AllDisjointClasses [ owl:members (
    ht:BloodPressureReading
    ht:Hypertension
    ht:SecondaryCause
    ht:TargetOrganDamage
    ht:Antihypertensive
    ht:RiskFactor
    ht:RetinalFinding
    ht:BloodPressureMeasurementTechnique
    ht:BloodPressureMeasurementSetting
) ] .
